/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Legal_TitleInputs */

const en_legal_title = /** @type {(inputs: Legal_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Legal Center & Trust Architecture`)
};

const vi_legal_title = /** @type {(inputs: Legal_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Trung tâm Pháp lý & Cam kết Minh bạch`)
};

/**
* | output |
* | --- |
* | "Legal Center & Trust Architecture" |
*
* @param {Legal_TitleInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const legal_title = /** @type {((inputs?: Legal_TitleInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Legal_TitleInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_legal_title(inputs)
	return en_legal_title(inputs)
});