import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Tab_SlaInputs */

const en_tab_sla = /** @type {(inputs: Tab_SlaInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`SLA Guarantee`)
};

const vi_tab_sla = /** @type {(inputs: Tab_SlaInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Cam kết Mức Dịch vụ (SLA)`)
};

/**
* | output |
* | --- |
* | "SLA Guarantee" |
*
* @param {Tab_SlaInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const tab_sla = /** @type {((inputs?: Tab_SlaInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Tab_SlaInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_tab_sla(inputs)
	return en_tab_sla(inputs)
});