import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Tab_PrivacyInputs */

const en_tab_privacy = /** @type {(inputs: Tab_PrivacyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Privacy Policy`)
};

const vi_tab_privacy = /** @type {(inputs: Tab_PrivacyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Chính sách Quyền riêng tư`)
};

/**
* | output |
* | --- |
* | "Privacy Policy" |
*
* @param {Tab_PrivacyInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const tab_privacy = /** @type {((inputs?: Tab_PrivacyInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Tab_PrivacyInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_tab_privacy(inputs)
	return en_tab_privacy(inputs)
});