/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Tab_TermsInputs */

const en_tab_terms = /** @type {(inputs: Tab_TermsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Terms of Service`)
};

const vi_tab_terms = /** @type {(inputs: Tab_TermsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Điều khoản Dịch vụ`)
};

/**
* | output |
* | --- |
* | "Terms of Service" |
*
* @param {Tab_TermsInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const tab_terms = /** @type {((inputs?: Tab_TermsInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Tab_TermsInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_tab_terms(inputs)
	return en_tab_terms(inputs)
});