import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Tab_CookiesInputs */

const en_tab_cookies = /** @type {(inputs: Tab_CookiesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Cookie Policy`)
};

const vi_tab_cookies = /** @type {(inputs: Tab_CookiesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Chính sách Cookie`)
};

/**
* | output |
* | --- |
* | "Cookie Policy" |
*
* @param {Tab_CookiesInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const tab_cookies = /** @type {((inputs?: Tab_CookiesInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Tab_CookiesInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_tab_cookies(inputs)
	return en_tab_cookies(inputs)
});