/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Search_LegalInputs */

const en_search_legal = /** @type {(inputs: Search_LegalInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search legal terms & clauses (⌘K)...`)
};

const vi_search_legal = /** @type {(inputs: Search_LegalInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Tìm kiếm điều khoản pháp lý (⌘K)...`)
};

/**
* | output |
* | --- |
* | "Search legal terms & clauses (⌘K)..." |
*
* @param {Search_LegalInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const search_legal = /** @type {((inputs?: Search_LegalInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Search_LegalInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_search_legal(inputs)
	return en_search_legal(inputs)
});