import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Tab_LicensesInputs */

const en_tab_licenses = /** @type {(inputs: Tab_LicensesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Open Source Licenses`)
};

const vi_tab_licenses = /** @type {(inputs: Tab_LicensesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Giấy phép Mã nguồn Mở`)
};

/**
* | output |
* | --- |
* | "Open Source Licenses" |
*
* @param {Tab_LicensesInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const tab_licenses = /** @type {((inputs?: Tab_LicensesInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Tab_LicensesInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_tab_licenses(inputs)
	return en_tab_licenses(inputs)
});