/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Lang_SwitchInputs */

const en_lang_switch = /** @type {(inputs: Lang_SwitchInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Switch language`)
};

const vi_lang_switch = /** @type {(inputs: Lang_SwitchInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Đổi ngôn ngữ`)
};

/**
* | output |
* | --- |
* | "Switch language" |
*
* @param {Lang_SwitchInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const lang_switch = /** @type {((inputs?: Lang_SwitchInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Lang_SwitchInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_lang_switch(inputs)
	return en_lang_switch(inputs)
});