import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Tab_OverviewInputs */

const en_tab_overview = /** @type {(inputs: Tab_OverviewInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Legal Hub Overview`)
};

const vi_tab_overview = /** @type {(inputs: Tab_OverviewInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Tổng quan Pháp lý`)
};

/**
* | output |
* | --- |
* | "Legal Hub Overview" |
*
* @param {Tab_OverviewInputs} inputs
* @param {{ locale?: "en" | "vi" }} options
* @returns {LocalizedString}
*/
export const tab_overview = /** @type {((inputs?: Tab_OverviewInputs, options?: { locale?: "en" | "vi" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Tab_OverviewInputs, { locale?: "en" | "vi" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "vi") return vi_tab_overview(inputs)
	return en_tab_overview(inputs)
});